"""Static portfolio. Content is maintained in data/projects.json and data/artworks.json."""
from pathlib import Path
from html import escape as e
import json
R=Path(__file__).resolve().parent.parent
SITE='https://lucascasagrande.com'
P=json.loads((R/'data/projects.json').read_text()); A=json.loads((R/'data/artworks.json').read_text())

def head(title,desc,path='/',image='/assets/artworks/newart_02_1920.webp'):
 image=SITE+image if image.startswith('/') else image
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — Lucas Casagrande</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{SITE}{path}"><meta name="theme-color" content="#0b0c0b"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)} — Lucas Casagrande"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{SITE}{path}"><meta property="og:image" content="{image}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><link rel="preload" href="/assets/fonts/Syne-800.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">Saltar al contenido</a>'''
def nav():
 return '''<header class="site-head"><a class="brand" href="/" aria-label="Lucas Casagrande, inicio"><span>LUCAS</span><span>CASAGRANDE<i>.</i></span></a><button class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav">Menú +</button><nav class="nav-links" id="site-nav" aria-label="Navegación principal"><a href="/#selected">Trabajo</a><a href="/artworks/">Artworks</a><a href="/#live">Visuales</a><a href="/#about">Perfil</a><a href="/#contact" class="contact-link">Hablemos ↗</a></nav></header>'''
def footer():
 return '''<footer class="site-foot shell" id="contact"><p class="eyebrow">Un brief. Una idea. Un nuevo universo.</p><h2 style="margin-top:25px">Hagamos algo<br><em>que valga la mirada.</em></h2><a class="contact-email" href="mailto:lucas.g.casagrande@gmail.com">lucas.g.casagrande@gmail.com ↗</a><div class="foot-bottom"><div class="socials"><a href="https://vimeo.com/lucascasagrande" target="_blank" rel="noopener">Vimeo ↗</a><a href="https://www.linkedin.com/in/lucascasagrande/" target="_blank" rel="noopener">LinkedIn ↗</a><a href="https://www.instagram.com/lucas_bighouse/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.behance.net/lucascasagrande" target="_blank" rel="noopener">Behance ↗</a></div><span>© <span data-year>2026</span> Lucas Casagrande / Buenos Aires</span></div></footer></body></html>'''
def lightbox():
 return '''<div class="lightbox" role="dialog" aria-modal="true" aria-label="Obra ampliada" aria-hidden="true"><button type="button" class="lightbox-close" aria-label="Cerrar obra ampliada">×</button><img alt=""><p class="lightbox-title" aria-live="polite"></p><div class="lightbox-controls"><button type="button" data-prev aria-label="Obra anterior">←</button><button type="button" data-next aria-label="Obra siguiente">→</button></div></div>'''
def art(a,desc=False):
 return f'''<figure><button class="art-button" type="button" data-art="{a['image']}" data-title="{e(a['title'])}" aria-label="Ampliar {e(a['title'])}"><img src="{a['image']}" alt="{e(a['description'])}" loading="lazy" width="1000" height="1000"></button><figcaption><div class="art-caption"><strong>{e(a['title'])}</strong><span>{e(a['category'])}</span></div>{'<p class="art-description">'+e(a['description'])+'</p>' if desc else ''}</figcaption></figure>'''
def work(p):
 return f'''<a class="work-tile" href="/work/{p['slug']}/"><div class="work-image"><img src="{p['img']}" alt="{e(p['title'])}: {e(p['sub'])}" loading="lazy" width="1600" height="900"><span class="work-open" aria-hidden="true">↗</span></div><div class="work-meta"><div><h3>{e(p['title'])}</h3><p>{e(p['sub'])}</p></div><span class="work-num">{p['num']}</span></div></a>'''
def write(path,content):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)

featured=[next(x for x in P if x['slug']==s) for s in ['lamicell-v22','toyota','pandora','snapdragon-pro','noorus-fill','claro-cgi']]
home=head('Dirección de arte, motion y mundos digitales','Lucas Casagrande. Director de arte, motion designer y artista 3D. Trabajo comercial, artworks, visuales y formación desde Buenos Aires para el mundo.')+nav()+f'''
<main id="main">
<section class="intro shell"><div class="intro-copy"><p class="eyebrow">Dirección de arte / Motion / 3D</p><h1>Mundos<br>en <span class="italic">movimiento.</span></h1><p>Soy Lucas Casagrande. Construyo imágenes, piezas y universos visuales para marcas, pantallas y escenarios.</p><div class="actions"><a class="btn primary" href="/work/reel-2026/">Ver el reel</a><a class="btn" href="#selected">Explorar trabajo</a></div></div><figure class="intro-media"><span class="vertical-note">EXPERIMENTACIÓN / OFICIO / DIRECCIÓN</span><img src="/assets/artworks/newart_02_1920.webp" alt="Escultura digital de formas reflectantes bajo luz azul y roja" fetchpriority="high" width="1800" height="1800"><figcaption><span>Neon Studies / Archivo personal</span><a href="/artworks/">VER ARTWORKS ↗</a></figcaption></figure></section>
<div class="intro-index shell"><span>Buenos Aires, Argentina / Trabajo internacional</span><a href="#selected">01 — Trabajo</a><a href="/artworks/">02 — Artworks</a><a href="#live">03 — Visuales</a><span>Una selección en continuo movimiento</span></div>
<section class="section shell" id="selected"><div class="section-top"><div><p class="eyebrow">01 / Proyectos seleccionados</p><h2>Del concepto<br>a la <span class="italic">imagen.</span></h2></div><p>Una selección de proyectos donde la dirección visual se encuentra con el objeto, el movimiento y la experiencia.</p></div><div class="work-grid">{''.join(work(p) for p in featured)}</div><div class="section-end"><p>Más registros, lenguajes y maneras de resolver una idea.</p><a class="btn" href="/work/">Ver todos los proyectos</a></div></section>
<section class="section shell paper" id="artworks"><div class="section-top"><div><p class="eyebrow">02 / Artworks</p><h2>La búsqueda<br>también es <span class="italic">obra.</span></h2></div><p>Experimentos personales con forma, materia, espacio y atmósfera. Un lugar para probar lo que todavía no tiene un brief.</p></div><div class="art-preview">{''.join(art(a) for a in [A[1],A[2],A[3]])}</div><div class="section-end"><p>Escultura digital, paisajes posibles y mundos propios.</p><a class="btn" href="/artworks/">Entrar a la galería</a></div></section>
<section class="live shell" id="live"><div class="section-top"><div><p class="eyebrow">03 / Visuales, música y espacio</p><h2>La imagen<br>toma <span class="italic">el lugar.</span></h2></div><p>Del render a una pantalla de gran escala. El trabajo visual también puede habitar un escenario, una instalación o una sala.</p></div><div class="live-pair"><figure><img src="/assets/artworks/stage-mockup.webp" alt="Visualización conceptual de una obra de Lucas en pantalla LED de escenario" loading="lazy" width="1672" height="941"><figcaption class="mock-caption"><span>Artworks / Pantalla y visuales</span><span class="mock-tag">Visualización / mockup</span></figcaption></figure><figure><img src="/assets/artworks/gallery-mockup.webp" alt="Visualización conceptual de una obra de Lucas en una galería" loading="lazy" width="1672" height="941"><figcaption class="mock-caption"><span>Artworks / Escala de exposición</span><span class="mock-tag">Visualización / mockup</span></figcaption></figure></div><div class="reference-strip"><span>Referencias de trabajo<br>en música y eventos</span><span class="ref-logo cream"><img src="/assets/logos/creamfields.svg" alt="Creamfields" loading="lazy" width="210" height="65"></span><span class="ref-logo"><img src="/assets/logos/ultra.png" alt="Ultra Music Festival" loading="lazy" width="210" height="65"></span><strong>PopUp</strong></div></section>
<section class="about section shell" id="about"><figure class="about-image"><img src="/assets/lucas-portrait.jpg" alt="Lucas Casagrande" loading="lazy" width="1000" height="1000"><figcaption>Lucas Casagrande / Director de arte y motion designer</figcaption></figure><div class="about-copy"><p class="eyebrow">El recorrido detrás de la imagen</p><h2>El oficio antes<br>que la <span class="italic">herramienta.</span></h2><p class="about-lead">Más de quince años explorando cómo una idea se convierte en una imagen que se siente.</p><p class="about-body">Mi recorrido pasa por estudios, agencias, televisión y proyectos internacionales. Trabajé desde Argentina y Medio Oriente, y hoy conecto dirección de arte, motion, 3D e inteligencia artificial desde Buenos Aires.</p><p class="about-body">La experimentación siempre estuvo ahí: en los primeros reels, en los visuales y en las piezas personales. La IA suma herramientas a esa búsqueda. El criterio para elegir, dirigir y terminar una pieza sigue siendo el centro.</p><div class="timeline"><div class="timeline-row"><span>Primeros reels</span><p>Proyección de un reel en Ciudad Emergente, en una etapa temprana de mi recorrido.</p></div><div class="timeline-row"><span>Visuales / VJ</span><p>Trabajos vinculados a Creamfields, UMF y PopUp. La imagen como parte de una experiencia en vivo.</p></div><div class="timeline-row"><span>Compartir oficio</span><p>Dicté un curso de VJ en el CCK y fui docente en Domestika.</p></div><div class="timeline-row"><span>Hoy</span><p>Fundador y director creativo de CHIMICHURRI. Dirección visual, producción y formación para equipos.</p></div></div><div class="actions"><a class="btn" href="https://www.linkedin.com/in/lucascasagrande/" target="_blank" rel="noopener">Más sobre mi recorrido</a></div></div></section>
<section class="shell"><p class="eyebrow">Trabajemos juntos</p><div class="offer-row"><div class="offer"><h3>Una pieza. Un sistema.<br>Una dirección visual.</h3><p>Dirección de arte, motion y 3D para equipos que necesitan llevar una idea de la primera referencia a una entrega con identidad.</p><a href="mailto:lucas.g.casagrande@gmail.com?subject=Proyecto%20creativo">Contame tu proyecto ↗</a></div><div class="offer"><h3>Aprender desde<br>el trabajo real.</h3><p>Charlas y talleres sobre creatividad, producción visual e IA aplicada para organizaciones y equipos. Un enfoque construido desde la práctica.</p><a href="mailto:lucas.g.casagrande@gmail.com?subject=Charla%20o%20capacitaci%C3%B3n">Conversemos sobre capacitación ↗</a></div></div></section>
</main>{lightbox()}'''+footer()
write('index.html',home)

artpage=head('Artworks / Archivo experimental','Escultura digital, paisajes, materia y mundos propios. Una selección del archivo experimental de Lucas Casagrande.','/artworks/')+nav()+f'''<main id="main"><header class="gallery-head shell"><p class="eyebrow">Artworks / Archivo experimental</p><h1>Explorar<br><span class="italic">sin un brief.</span></h1><p>Imágenes que nacen de probar, desarmar y volver a mirar. Escultura digital, lugares imaginados y pequeños mundos con sus propias reglas.</p></header><section class="art-grid shell" aria-label="Galería de artworks">{''.join(art(a,True) for a in A)}</section><section class="shell"><div class="archive-link"><p>¿Una de estas imágenes te dispara una idea?</p><a class="btn primary" href="mailto:lucas.g.casagrande@gmail.com?subject=Artworks%20y%20visuales">Hablemos de visuales</a></div></section></main>{lightbox()}'''+footer()
write('artworks/index.html',artpage)

for i,p in enumerate(P):
 prev=P[(i-1)%len(P)];nxt=P[(i+1)%len(P)]
 if p.get('vid'):
  media=f'''<button class="video-load" type="button" data-vimeo="{p['vid']}" data-title="{e(p['title'])}" aria-label="Reproducir {e(p['title'])}"><img src="{p['img']}" alt="Imagen de {e(p['title'])}" loading="eager" width="1600" height="900"></button>'''
 else:media=f'''<img src="{p['img']}" alt="Imagen de {e(p['title'])}" width="1600" height="900">'''
 infos=[('Enfoque',' / '.join(p['tags']))]
 if p.get('role'):infos.append(('Participación',p['role']))
 if p.get('year'):infos.append(('Año',p['year']))
 inf=''.join(f'<dt>{e(k)}</dt><dd>{e(v)}</dd>' for k,v in infos)
 cta=f'<a class="btn primary" href="https://vimeo.com/{p["vid"]}" target="_blank" rel="noopener">Ver pieza en Vimeo</a>' if p.get('vid') else ''
 page=head(p['title'],p['sub']+'. '+p['body'],'/work/'+p['slug']+'/',p['img'])+nav()+f'''<main id="main"><header class="case-head shell"><p class="eyebrow">Trabajo / {p['num']}</p><h1>{e(p['title'])}</h1><p class="case-sub">{e(p['sub'])}</p><p class="case-tags">{''.join('<span>'+e(t)+'</span>' for t in p['tags'])}</p></header><section class="case-media" aria-label="Pieza audiovisual">{media}</section><section class="case-body shell"><div><p class="lead">{e(p['body'])}</p><p class="focus">{e(p['focus'])}</p><div class="actions">{cta}<a class="btn" href="mailto:lucas.g.casagrande@gmail.com?subject=Proyecto%20creativo">Hablemos de un proyecto</a></div></div><aside class="case-info"><dl>{inf}</dl></aside></section><nav class="case-pager shell" aria-label="Más proyectos"><a href="/work/{prev['slug']}/"><small>← Proyecto anterior</small><strong>{e(prev['title'])}</strong></a><a href="/work/{nxt['slug']}/"><small>Proyecto siguiente →</small><strong>{e(nxt['title'])}</strong></a></nav></main>'''+footer()
 write('work/'+p['slug']+'/index.html',page)
allpage=head('Trabajo / Selección de proyectos','Una selección de proyectos de motion, CGI, 3D e identidad audiovisual de Lucas Casagrande.','/work/')+nav()+f'''<main id="main"><header class="gallery-head shell"><p class="eyebrow">Trabajo / Una selección del recorrido</p><h1>Ideas que<br><span class="italic">tomaron forma.</span></h1><p>Proyectos, piezas y lenguajes visuales. Una selección de mi trabajo entre el objeto, el espacio y la imagen en movimiento.</p></header><section class="all-grid shell" aria-label="Todos los proyectos">{''.join(work(p) for p in P)}</section></main>'''+footer()
write('work/index.html',allpage)
urls=['/','/artworks/','/work/']+[f'/work/{p["slug"]}/' for p in P]
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{SITE}{u}</loc></url>' for u in urls)+'</urlset>\n')
write('robots.txt','User-agent: *\nAllow: /\nSitemap: '+SITE+'/sitemap.xml\n')
print(f'Generated home, artworks, work index and {len(P)} case pages. {sum(bool(p.get("vid")) for p in P)} exact Vimeo IDs.')
